// CSD_RATIONALE_BEGIN
// Solve math word problems step by step, writing each arithmetic computation inside << >> delimiters.
// Start with unconstrained reasoning to understand the problem, then switch to constrained generation to produce valid mathematical expressions.
// Use ConfidenceGatedStep to ensure we don't prematurely end the solution.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var insideConstrained: bool := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  invariant insideConstrained ==> forall t: Token :: t in parser.ValidNextTokens(currentConstrained) ==> t in lm.Tokens
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  if !insideConstrained {
    // Unconstrained step: generate a token that is either part of the problem statement or a potential operation
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;
    if Contains(next, "<<") {
      insideConstrained := true;
      currentConstrained := [];
      CSDHelpers.RollbackPreservesTokenInvariant(lm, parser, []);
    }
  } else {
    if parser.IsCompletePrefix(currentConstrained) {
      insideConstrained := false;
    } else {
      // Constrained step: generate a token that is a valid grammar continuation and part of a valid mathematical expression
      var next, wasConstrained := helpers.ConfidenceGatedStep(lm, parser, prompt, currentConstrained);
      generated := generated + [next];
      currentConstrained := currentConstrained + [next];
      steps := steps + 1;
      if Contains(next, ">>") { insideConstrained := false; }
    }
  }
}
cost := helpers.cost;

